ALTER TABLE asterisk.voice_agent_versions DROP CONSTRAINT IF EXISTS voice_agent_contract_check;
ALTER TABLE asterisk.voice_agent_versions ADD CONSTRAINT IF NOT EXISTS voice_agent_contract_check CHECK (workflow_version > 0 AND contract_version IN (1,2,3));
CREATE OR REPLACE SQL SECURITY DEFINER VIEW asterisk.voice_agent_runtime_tools AS SELECT tool_id,tool_version,manifest_json FROM asterisk.voice_agent_builtin_tools WHERE tool_version IN (1,2);
